# PUT /api/sheets/{sheetId}/people/{personId}/flag — a steward flags the person. Body {"reason":"...","until":"yyyy-mm-dd"}
# (a blank until-date is the sheet's today); it replaces any flag they had (PERSON_FLAGGED). While the sheet's today is on
# or before the until-date, only a steward may open the person's claims. 400 for anyone but a steward, a blank reason or
# a date that is not real, and nothing is stored; 404 for a person not on the sheet.
viewer:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: archived
  govern: [ transaction ]
archived:
  class: net.officefloor.hq.app.sheet.RefuseArchived
  next: validate
  govern: [ transaction ]
validate:
  class: net.officefloor.hq.app.flag.ValidateFlag
  next: load
  govern: [ transaction ]
load:
  class: net.officefloor.hq.app.person.LoadPerson
  next: apply
  govern: [ transaction ]
apply:
  class: net.officefloor.hq.app.flag.ApplyFlag
  next: respond
  govern: [ transaction ]
respond:
  class: net.officefloor.hq.app.flag.RespondWithFlag
  govern: [ transaction ]
# PUT /api/sheets/{sheetId}/people/{personId}/hold — add a hold to a person. Body
# {"from":"yyyy-mm-dd","to":"yyyy-mm-dd"}; a blank from-date is the sheet's today, a blank to-date has no
# end (a hold ends on its to-date). Their OPEN claims dated within a hold and not bound by a statement
# count in no live total. A date that is not real, or a to-date before the from-date, is refused with 400
# and nothing is stored; 404 for a person not on the sheet.
viewer:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: archived
  govern: [ transaction ]
archived:
  class: net.officefloor.hq.app.sheet.RefuseArchived
  next: validate
  govern: [ transaction ]
validate:
  class: net.officefloor.hq.app.person.ValidateHold
  next: snapshot
  govern: [ transaction ]
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  next: load
  govern: [ transaction ]
load:
  class: net.officefloor.hq.app.person.LoadPerson
  next: hold
  govern: [ transaction ]
hold:
  class: net.officefloor.hq.app.person.HoldPerson
  next: audit
  govern: [ transaction ]
audit:
  class: net.officefloor.hq.app.person.AuditPersonHeld
  next: rollup
  govern: [ transaction ]
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  next: respond
  govern: [ transaction ]
respond:
  class: net.officefloor.hq.app.person.RespondWithEditedPerson
  govern: [ transaction ]
