package net.officefloor.hq.app.flag;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class ApplyFlag {
    // Flagging replaces any flag the person had, and is recorded as PERSON_FLAGGED.
    public void apply(@Val Flag flag, @Val Person person, Flags flags, Sheets sheets, ServerHttpConnection connection,
            Audit audit, Out<FlagResponse> responseOut) {
        flags.set(person.id(), flag.reason(), flag.until());
        audit.record(Audit.line("PERSON_FLAGGED", person.sheetId(), Audit.user(connection), "name=" + person.name(),
                "reason=" + flag.reason(), "until=" + flag.until()));
        responseOut.set(FlagResponse.from(new Flag(person.id(), flag.reason(), flag.until()),
                sheets.today(person.sheetId())));
    }
}
package net.officefloor.hq.app.flag;

import java.time.LocalDate;

/** A person's flag: its reason, in force while the sheet's today is on or before {@code until}. */
public record Flag(long personId, String reason, LocalDate until) {

    /** Whether the flag is in force on the date (on or before its until-date). */
    public boolean inForceOn(LocalDate date) {
        return date != null && !date.isAfter(until);
    }
}
package net.officefloor.hq.app.flag;

/** The body of flagging a person: the reason and the until-date (yyyy-mm-dd; blank: the sheet's today), as typed. */
public record FlagRequest(String reason, String until) {
}
package net.officefloor.hq.app.flag;

/**
 * A person's flag as the screen sees it: its reason and until-date (yyyy-mm-dd), and {@code shown}, the reason while
 * the sheet's today is on or before the until-date, else blank.
 */
public record FlagResponse(long personId, String reason, String until, String shown) {

    public static FlagResponse from(Flag flag, java.time.LocalDate today) {
        return new FlagResponse(flag.personId(), flag.reason(), flag.until().toString(),
                flag.inForceOn(today) ? flag.reason() : "");
    }
}
package net.officefloor.hq.app.flag;

import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The store of the people's flags, kept per sheet through the people. */
@Repository
public class Flags {

    private static final RowMapper<Flag> ROW = (rs, n) -> new Flag(rs.getLong("person_id"), rs.getString("reason"),
            rs.getObject("until_date", LocalDate.class));

    private final JdbcTemplate jdbc;

    public Flags(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every flag on the sheet's people. */
    public List<Flag> list(String sheetId) {
        return jdbc.query("SELECT f.* FROM person_flag f JOIN person p ON p.id = f.person_id WHERE p.sheet_id = ?",
                ROW, sheetId);
    }

    /** The person's flag; null when they have none. */
    public Flag find(long personId) {
        List<Flag> found = jdbc.query("SELECT * FROM person_flag WHERE person_id = ?", ROW, personId);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether the person has a flag in force on the date. */
    public boolean flaggedOn(long personId, LocalDate date) {
        Flag flag = find(personId);
        return flag != null && flag.inForceOn(date);
    }

    /** Flag the person, replacing any flag they had. */
    public void set(long personId, String reason, LocalDate until) {
        jdbc.update("DELETE FROM person_flag WHERE person_id = ?", personId);
        jdbc.update("INSERT INTO person_flag (person_id, reason, until_date) VALUES (?, ?, ?)", personId, reason,
                Date.valueOf(until));
    }
}
package net.officefloor.hq.app.flag;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithFlag {
    public void respond(@Val FlagResponse flag, ObjectResponse<FlagResponse> response) {
        response.send(flag);
    }
}
package net.officefloor.hq.app.flag;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithFlags {
    public void respond(@PathVariable("sheetId") String sheetId, Flags flags, Sheets sheets,
            ObjectResponse<List<FlagResponse>> response) {
        String sheet = sheetId.trim();
        LocalDate today = sheets.today(sheet);
        response.send(flags.list(sheet).stream().map(f -> FlagResponse.from(f, today)).toList());
    }
}
package net.officefloor.hq.app.flag;

import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.InvalidPersonException;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateFlag {

    private static final DateTimeFormatter ISO = DateTimeFormatter.ofPattern("uuuu-MM-dd")
            .withResolverStyle(ResolverStyle.STRICT);

    // Only a steward (by the role they act in on the sheet's today) flags, and only with a reason; a blank until-date
    // is the sheet's today.
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody FlagRequest body, Settings settings,
            Sheets sheets, ServerHttpConnection connection, Out<Flag> flag) throws InvalidPersonException {
        String sheet = sheetId.trim();
        if (!Settings.STEWARD.equals(settings.role(sheet, Audit.user(connection).trim()))) {
            throw new InvalidPersonException("Only a steward can flag a person.");
        }
        String reason = body == null || body.reason() == null ? "" : body.reason().trim();
        if (reason.isEmpty()) {
            throw new InvalidPersonException("Give a reason to flag the person.");
        }
        String raw = body.until() == null ? "" : body.until().trim();
        LocalDate until;
        try {
            until = raw.isEmpty() ? sheets.today(sheet) : LocalDate.parse(raw, ISO);
        } catch (DateTimeParseException e) {
            throw new InvalidPersonException("Not a date (yyyy-mm-dd): " + raw);
        }
        flag.set(new Flag(0, reason, until));
    }
}
